func newUploadMdfClaimFileCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "upload-mdf-claim-file",
		Short: "Upload partner portal MDF claim file",
		Long:  "Attach one supporting file (invoice, proof of performance) to a market development funds claim that belongs to the authenticated partner organization and is in Submitted status. Multipart form fields: mdfClaimId, portalFileId and exactly one file part named file. The file must be 24 MB or smaller and one of PDF, PNG, JPEG, HEIC, DOC, DOCX, XLS, XLSX or CSV; a claim holds at most 10 files. portalFileId is generated by the client and resent unchanged on retry, so retrying returns the already-uploaded file instead of creating a duplicate.\n\nPartner-only: runs as your partner organization, so --partner-org (or a profile's client org) is not sent.\n\nMultipart upload: pass each form field as --field name=value and the file as --file path (part \"file\"), or --file part=path for another part name.",
		RunE: func(cmd *cobra.Command, args []string) error {
			cfg := config.LoadFromCmd(cmd)
			cfg.PartnerOrg = ""
			fieldArgs, _ := cmd.Flags().GetStringArray("field")
			fileArgs, _ := cmd.Flags().GetStringArray("file")
			fields, err := params.ParseFormFields(fieldArgs)
			if err != nil {
				return err
			}
			files, err := params.ParseFileParts(fileArgs)
			if err != nil {
				return err
			}
			result, err := client.MultipartCall(cfg, "/api/partnerportal/uploadMdfClaimFile", fields, files)
			if err != nil {
				return err
			}
			return output.FormatOutput(cmd, result)
		},
	}
	cmd.Flags().StringArray("field", nil, "Form field as name=value (repeatable)")
	cmd.Flags().StringArray("file", nil, "File to upload: path (sent as part \"file\") or part=path (repeatable)")
	return cmd
}

